commands:
WP_BRANCH=""
PR_JSON='[]'
[ -n "$WP_BRANCH" ] && { PR_JSON=$(gh pr list --head "$WP_BRANCH" --state open --json number,headRefName,createdAt,closingIssuesReferences,isCrossRepository) || PR_JSON=''; }
[ "$PR_JSON" = "[]" ] && { PR_JSON=$(gh pr list --search "1659 in:body" --state open --json number,headRefName,createdAt,closingIssuesReferences,isCrossRepository) || PR_JSON=''; }
echo "PR_JSON=$PR_JSON"
